import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI, booksAPI } from '../utils/api';
import { clearUserSession, getStoredUser, saveUserSession } from '../utils/session';

const Dashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [bookForm, setBookForm] = useState({
    bookTitle: '',
    author: '',
    language: ''
  });
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    const storedUser = getStoredUser();

    if (!storedUser) {
      navigate('/login', { replace: true });
      return;
    }

    const loadDashboard = async () => {
      try {
        const [userResponse] = await Promise.all([
          authAPI.getUser(storedUser.id),
          fetchUserBooks(storedUser.id)
        ]);

        const currentUser = saveUserSession(userResponse.data.user);
        setUser(currentUser);
      } catch (err) {
        clearUserSession();
        navigate('/login', { replace: true });
      } finally {
        setLoading(false);
      }
    };

    loadDashboard();
  }, [navigate]);

  const fetchUserBooks = async (userId) => {
    const response = await booksAPI.getUserBooks(userId);
    setBooks(response.data.books);
  };

  const handleBookFormChange = (e) => {
    const { name, value } = e.target;
    setBookForm(prev => ({
      ...prev,
      [name]: value
    }));
    setError('');
  };

  const handleSubmitBook = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const bookTitle = bookForm.bookTitle.trim();
    const author = bookForm.author.trim();
    const language = bookForm.language.trim();

    if (!bookTitle || !author || !language) {
      setError('Please enter the book title, author, and language');
      return;
    }

    setSubmitting(true);

    try {
      await booksAPI.addBook(user.id, {
        bookTitle,
        author,
        language
      });

      setBookForm({
        bookTitle: '',
        author: '',
        language: ''
      });
      setSuccess('Book added successfully.');

      await fetchUserBooks(user.id);

      const updatedUser = {
        ...user,
        booksReadCount: (user.booksReadCount || 0) + 1
      };
      setUser(updatedUser);
      saveUserSession(updatedUser);

      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to add book. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleLogout = () => {
    clearUserSession();
    navigate('/');
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading your dashboard...</p>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div>
      <div className="header">
        <div className="header-content header-actions">
          <div>
            <h1>Your Reading Dashboard</h1>
            <p>Gift of Reading Initiative</p>
          </div>
          <button onClick={handleLogout} className="btn btn-secondary">
            Logout
          </button>
        </div>
      </div>

      <div className="container">
        <div className="card welcome-card">
          <h2>Welcome, {user.firstName}!</h2>
          <p>{user.location}</p>
          {user.category === 'Student' && user.class !== 'N/A' && (
            <p>Class: {user.class}</p>
          )}
        </div>

        <div className="dashboard-grid">
          <div className="card">
            <h3 className="section-title">Your Reading Journey</h3>
            <div style={{ textAlign: 'center' }}>
              <div className="books-count">
                <div style={{ fontSize: '3rem', fontWeight: 'bold' }}>
                  {user.booksReadCount || 0}
                </div>
                <div style={{ fontSize: '0.9rem' }}>
                  Books Read
                </div>
              </div>
              <p style={{ color: 'var(--color-muted-text)', fontSize: '1.1rem' }}>
                {user.booksReadCount > 0
                  ? 'Good progress. Keep reading.'
                  : 'Start your reading journey today.'}
              </p>
            </div>
          </div>

          <div className="card">
            <h3 className="section-title">Record a New Book</h3>

            {error && <div className="error">{error}</div>}
            {success && <div className="success">{success}</div>}

            <form onSubmit={handleSubmitBook}>
              <div className="form-group">
                <label>Book Title</label>
                <input
                  type="text"
                  name="bookTitle"
                  value={bookForm.bookTitle}
                  onChange={handleBookFormChange}
                  placeholder="Enter the book title"
                  disabled={submitting}
                />
              </div>

              <div className="form-group">
                <label>Author</label>
                <input
                  type="text"
                  name="author"
                  value={bookForm.author}
                  onChange={handleBookFormChange}
                  placeholder="Enter the author's name"
                  disabled={submitting}
                />
              </div>

              <div className="form-group">
                <label>Language</label>
                <select
                  name="language"
                  value={bookForm.language}
                  onChange={handleBookFormChange}
                  disabled={submitting}
                >
                  <option value="">Select language</option>
                  <option value="English">English</option>
                  <option value="Urdu">Urdu</option>
                  <option value="Sindhi">Sindhi</option>
                  <option value="Gujarati">Gujarati</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              <button
                type="submit"
                className="btn"
                style={{ width: '100%' }}
                disabled={submitting}
              >
                {submitting ? 'Adding...' : 'Add Book'}
              </button>
            </form>
          </div>
        </div>

        <div className="card">
          <h3 className="section-title">
            Your Reading History ({books.length} books)
          </h3>

          {books.length === 0 ? (
            <div className="empty-state">
              <p>No books recorded yet. Start adding the books you've read.</p>
            </div>
          ) : (
            <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Book Title</th>
                    <th>Author</th>
                    <th>Language</th>
                    <th>Date Recorded</th>
                  </tr>
                </thead>
                <tbody>
                  {books.map((book, index) => (
                    <tr key={book.id}>
                      <td>{books.length - index}</td>
                      <td style={{ fontWeight: '500' }}>{book.bookTitle}</td>
                      <td>{book.author}</td>
                      <td>{book.language}</td>
                      <td style={{ color: 'var(--color-muted-text)' }}>
                        {new Date(book.recordedAt).toLocaleDateString('en-US', {
                          year: 'numeric',
                          month: 'short',
                          day: 'numeric'
                        })}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="card" style={{ textAlign: 'center' }}>
          <button
            onClick={() => navigate('/')}
            className="btn"
          >
            View Global Tracker
          </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
